const app = document.getElementById('app');
JSON.stringify({
  title: document.title,
  view: app ? app.dataset.view : null,
  motion: app ? getComputedStyle(app).getPropertyValue('--motion').trim() : null,
  panels: ['.upgrade-panel','.nav','.resource-bar','.inventory-panel'].map(s => {
    const n = document.querySelector(s);
    if (!n) return [s, null];
    const b = n.getBoundingClientRect();
    return [s, {x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height)}];
  })
});

const nav = document.querySelector('.nav-upgrades');
const panel = document.querySelector('.upgrade-panel');
const before = panel.getBoundingClientRect();
nav.click();
const after = panel.getBoundingClientRect();
const flips = [];
for (const sel of ['.upgrade-panel','.nav','.resource-bar','.hull-bar','.wave-card']) {
  const n = document.querySelector(sel);
  if (!n) continue;
  const a = n.getAnimations().filter(x => x.id === 'flip');
  flips.push([sel, a.length, a[0] ? a[0].effect.getTiming().duration : null]);
}
JSON.stringify({
  view: document.getElementById('app').dataset.view,
  panelBefore: {y: Math.round(before.y), h: Math.round(before.height)},
  panelAfter:  {y: Math.round(after.y),  h: Math.round(after.height)},
  flips,
  pinned: [...document.querySelectorAll('[data-leaving]')].map(n => n.className)
});

function sampleSwitch(navSel, watchSel) {
  const n = document.querySelector(watchSel);
  const before = n.getBoundingClientRect();
  document.querySelector(navSel).click();
  const after = n.getBoundingClientRect();
  const a = n.getAnimations().filter(x => x.id === 'flip')[0];
  const path = [];
  if (a) {
    for (const f of [0, 0.15, 0.4, 1]) {
      a.currentTime = 420 * f;
      const b = n.getBoundingClientRect();
      path.push([f, Math.round(b.x), Math.round(b.y), Math.round(b.width), Math.round(b.height)]);
    }
    a.currentTime = 0; a.play();
  }
  return {
    view: document.getElementById('app').dataset.view,
    before: {x: Math.round(before.x), y: Math.round(before.y), w: Math.round(before.width), h: Math.round(before.height)},
    after:  {x: Math.round(after.x),  y: Math.round(after.y),  w: Math.round(after.width),  h: Math.round(after.height)},
    hasFlip: !!a, path,
    departing: [...document.querySelectorAll('[data-leaving]')].map(x => x.className.split(' ')[0])
  };
}
JSON.stringify(sampleSwitch('.nav-base', '.upgrade-panel'));

