// Bewegung abschalten und pruefen, dass kein Flug mehr entsteht
const app = document.getElementById('app');
const prev = app.dataset.motion;
app.dataset.motion = 'off';
out['_motionVar'] = getComputedStyle(app).getPropertyValue('--motion').trim();
document.querySelector('.nav-base').click();
out['_flipsWhileOff'] = [...document.querySelectorAll('*')].filter(n => n.getAnimations && n.getAnimations().some(a => a.id === 'flip')).length;
out['_viewAfter'] = app.dataset.view;
if (prev === undefined) delete app.dataset.motion; else app.dataset.motion = prev;
JSON.stringify(out);

