const panel = document.querySelector('.upgrade-panel');
const settled = getComputedStyle(panel).transform;   // Ruhezustand, Auftritt ist durch
const before = panel.getBoundingClientRect();
document.querySelector('.nav-upgrades').click();
const a = panel.getAnimations().filter(x => x.id === 'flip')[0];
const path = [];
if (a) {
  for (const f of [0, 0.1, 0.25, 0.5, 1]) {
    a.currentTime = 420 * f;
    const b = panel.getBoundingClientRect();
    path.push([f, Math.round(b.y), Math.round(b.height)]);
  }
  a.currentTime = 0; a.play();
}
JSON.stringify({settled, before: {y: Math.round(before.y), h: Math.round(before.height)}, hasFlip: !!a, path});

const panel = document.querySelector('.upgrade-panel');
JSON.stringify({
  now: getComputedStyle(panel).transform,
  animations: panel.getAnimations().map(a => ({
