(() => {
  const t0 = document.timeline.currentTime;
  const start = performance.now();
  while (performance.now() - start < 120) { /* busy wait, 120 ms Wanduhr */ }
  return JSON.stringify({
    timelineStart: Math.round(t0),
    timelineEnd: Math.round(document.timeline.currentTime),
    wallClockMs: Math.round(performance.now() - start),
    hidden: document.hidden, visibility: document.visibilityState
  });
})();
